public static void check(Solution solution) {
    assert Arrays.equals(solution.mostPopularCreator(new int[]{"eve","eve","eve","eve"}, new int[]{"a","a","b","b"}, new int[]{10,20,20,10}), new int[]{{'eve', 'a'}});
    assert Arrays.equals(solution.mostPopularCreator(new int[]{"alice","bob","alice","chris"}, new int[]{"one","two","three","four"}, new int[]{5,10,5,4}), new int[]{{'alice', 'one'}, {'bob', 'two'}});
    assert Arrays.equals(solution.mostPopularCreator(new int[]{"john","john","john"}, new int[]{"x","y","x"}, new int[]{10,10,10}), new int[]{{'john', 'x'}});
    assert Arrays.equals(solution.mostPopularCreator(new int[]{"anna","bob","charlie"}, new int[]{"a","b","c"}, new int[]{100,200,300}), new int[]{{'charlie', 'c'}});
    assert Arrays.equals(solution.mostPopularCreator(new int[]{"alice","alice","alice"}, new int[]{"a","b","c"}, new int[]{1,2,2}), new int[]{{'alice', 'b'}});
